echo (int)$a . "/" . (int)$b;

switch (2) {
    case 2: echo "X";
    case 3: echo "Y"; break;
}

function size(...$values) {
    return count($values);
}
echo size(4, 5);

class BaseLabel { public function text() { return "base"; } }
class ChildLabel extends BaseLabel { public function text() { return "child"; } }
echo (new ChildLabel())->text();

class Counter { public static $n = 0; }
Counter::$n += 3;
echo Counter::$n;

class Card { public $color = "red"; }
$a = new Card();
$b = $a;
$b->color = "blue";
echo $a->color;

class Box { public $n = 5; }
$a = new Box();
$b = clone $a;
$b->n = 9;
echo $a->n . "/" . $b->n;

class Animal {}
class Cat extends Animal {}
var_dump((new Cat()) instanceof Animal);

try {
    throw new Exception("stop");
    echo "T";
} catch (Exception $e) {
    echo "C";
} finally {
    echo "F";
}

$s = '';
switch (2) {
    case 1: $s .= 'A';
    case 2: $s .= 'B';
    case 3: $s .= 'C'; break;
    default: $s .= 'D';
}
echo $s;

$score = 85;
if ($score >= 60) { echo 'pass'; }
elseif ($score >= 80) { echo 'excellent'; }
else { echo 'retry'; }

function tick() { static $n = 0; return ++$n; }
$a = tick();
$b = tick();
echo $a . ':' . $b;

function sumDown($n) {
    if ($n <= 0) { return 0; }
    return $n + sumDown($n - 1);
}
echo sumDown(3);

function label($name, $prefix = 'Hi', $suffix = '!') {
    return $prefix . ' ' . $name . $suffix;
}
echo label(suffix: '?', name: 'Mio');

$a = new DateTimeImmutable('2026-10-10', new DateTimeZone('UTC'));
