$a = new DateTimeImmutable('2026-10-10', new DateTimeZone('UTC'));
$b = new DateTimeImmutable('2026-10-13', new DateTimeZone('UTC'));
echo $a->diff($b)->format('%a');

$d = new DateTimeImmutable('2026-01-01 00:00:00', new DateTimeZone('UTC'));
$j = $d->setTimezone(new DateTimeZone('Asia/Tokyo'));
